Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
function Assert-RootEnumerationPins([string]$Run,[string]$Source,[string]$Shadow){if($Run -cne 'd391186e9f21450e92a8dc4711c4c747' -or $Source -cne '7136491eb3cbeb5fc23dbcac3f62af78bd991dde8bb7997cbd4215c9e48e3208' -or $Shadow -cne '55e3c20142b8b993cf69277866a0ee4b65d271580d915814a1ba1051d57d57f8'){throw 'Exact failed preparation case required.'}}
function Assert-RootEnumerationOrdinary([string]$Path,[bool]$Directory){$f=Get-Item -LiteralPath $Path -Force;if([bool]$f.PSIsContainer -ne $Directory -or ($f.Attributes -band ([IO.FileAttributes]::ReparsePoint -bor [IO.FileAttributes]::Compressed -bor [IO.FileAttributes]::Encrypted))){throw 'Ordinary diagnostic/evidence path required.'};$f}
function Read-RootEnumerationPin([string]$Path,[string]$Hash,[long]$Maximum,[switch]$Text){$p=[IO.Path]::GetDirectoryName($Path);while($p){Assert-RootEnumerationOrdinary $p $true|Out-Null;$p=[IO.Path]::GetDirectoryName($p)};$f=Assert-RootEnumerationOrdinary $Path $false;if($f.Length -lt 1 -or $f.Length -gt $Maximum){throw 'Pinned diagnostic input bound differs.'};$stream=New-Object IO.FileStream($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$script:held.Add($stream);$sha=[Security.Cryptography.SHA256]::Create();try{$actual=[BitConverter]::ToString($sha.ComputeHash($stream)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};if($actual -cne $Hash){throw 'Diagnostic input hash differs.'};$stream.Position=0;$reader=New-Object IO.StreamReader($stream,(New-Object Text.UTF8Encoding($false,$true)),$true,4096,$true);try{$value=$reader.ReadToEnd()}finally{$reader.Dispose()};if($Text){$value}else{$value|ConvertFrom-Json}}
function Assert-RootEnumerationProofs($Source,$Shadow,[string]$Run){
 if($Source.schemaVersion -ne 1 -or $Source.kind -cne 'retained-ntfs-source-platform' -or $Source.runId -cne $Run -or $Source.status -cne 'ntfs-source-prepared' -or $Source.operationCompletionKnown -isnot [bool] -or -not $Source.operationCompletionKnown -or $Source.partition.number -ne 2 -or $Source.partition.offset -ne 16MB -or $Source.partition.length -ne 52GB -or $Source.partition.logicalSectorSize -ne 512 -or $Source.partition.physicalSectorSize -ne 4096 -or $Source.target.guest.uniqueId -cne '60022480D091C4251B5FFD619706C2B5'){throw 'Exact completed source proof differs.'}
 if($Shadow.schemaVersion -ne 1 -or $Shadow.kind -cne 'guest-local-shadow-platform' -or $Shadow.runId -cne $Run -or $Shadow.status -cne 'shadow-platform-prepared' -or $Shadow.nativeOperationCompletionKnown -isnot [bool] -or -not $Shadow.nativeOperationCompletionKnown -or $Shadow.shadow.diskNumber -ne 3 -or $Shadow.shadow.diskUniqueId -cne '60022480AC3AF41D01E82B96C0CA99F4' -or $Shadow.shadow.partitionNumber -ne 2 -or $Shadow.shadow.offset -ne 16MB -or $Shadow.shadow.length -ne 52GB){throw 'Exact completed shadow proof differs.'}
 foreach($pair in @(@($Source.partition.diskGuid,'4922a5f5-efb8-4291-a7f6-84e67f41c6b1'),@($Source.partition.guid,'9022a6b7-7462-4834-8400-7099267b2ec2'),@($Shadow.shadow.diskGuid,'6725fd86-2a7e-4931-a418-e4d6eae08d2e'),@($Shadow.shadow.partitionGuid,'7514561b-6c7b-4009-8f08-3fb6744f2ae2'))){if([guid]$pair[0] -ne [guid]$pair[1]){throw 'Failed-case GPT identity differs.'}}
}
function Assert-RootEnumerationInventory([object[]]$Disks){$ids=@('60022480BEA35BA9D496D5AFF633D768','60022480D091C4251B5FFD619706C2B5','600224806AAC261F021F249596F332FC','60022480AC3AF41D01E82B96C0CA99F4');if($Disks.Count -ne 4){throw 'Exact four-disk diagnostic inventory required.'};for($i=0;$i -lt 4;$i++){$d=@($Disks|Where-Object Number -EQ $i);if($d.Count -ne 1 -or $d[0].UniqueId -cne $ids[$i] -or $d[0].Size -ne $(if($i -eq 2){8GB}else{64GB}) -or $d[0].LogicalSectorSize -ne 512 -or $d[0].PhysicalSectorSize -ne 4096 -or $d[0].IsOffline -or $d[0].IsReadOnly -or [bool]$d[0].IsBoot -ne ($i -eq 0) -or [bool]$d[0].IsSystem -ne ($i -eq 0)){throw 'Diagnostic disk enrollment/state differs.'}}}
function Assert-RootEnumerationLive($Disk,$Part,$Volume,$Proof,[string]$Role){$s=if($Role -ceq 'A'){$Proof.partition}else{$Proof.shadow};$number=if($Role -ceq 'A'){1}else{3};$guid=if($Role -ceq 'A'){$s.guid}else{$s.partitionGuid};$vg=if($Role -ceq 'A'){$Proof.volume.guid}else{$s.volumeGuid};$fs=if($Role -ceq 'A'){'NTFS'}else{'ReFS'};$letter=if($Role -ceq 'A'){'F'}else{'S'};$label=if($Role -ceq 'A'){'n2r-retained-source'}else{'n2r-retained-shadow'};if($Role -cnotin @('A','B') -or $Disk.Number -ne $number -or $Disk.PartitionStyle -cne 'GPT' -or [guid]$Disk.Guid -ne [guid]$s.diskGuid -or $Part.DiskNumber -ne $number -or $Part.PartitionNumber -ne 2 -or [guid]$Part.Guid -ne [guid]$guid -or $Part.Offset -ne 16MB -or $Part.Size -ne 52GB -or $Part.GptType -ine '{ebd0a0a2-b9e5-4433-87c0-68b6b72699c7}' -or [string]$Part.DriveLetter -cne $letter -or $Part.IsBoot -or $Part.IsSystem -or $Volume.UniqueId -ine $vg -or $Volume.FileSystem -cne $fs -or $Volume.FileSystemLabel -cne $label -or $Volume.AllocationUnitSize -ne 4096){throw 'Exact diagnostic volume/GPT binding differs.'}}
function New-RootEnumerationDirectory([string]$Path){if(Test-Path -LiteralPath $Path){throw 'Create-new private diagnostic path exists.'};New-Item -ItemType Directory -Path $Path|Out-Null;$acl=New-Object Security.AccessControl.DirectorySecurity;$acl.SetAccessRuleProtection($true,$false);foreach($sid in @('S-1-5-18','S-1-5-32-544')){$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier($sid)),[Security.AccessControl.FileSystemRights]::FullControl,([Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [Security.AccessControl.InheritanceFlags]::ObjectInherit),[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow)))};Set-Acl -LiteralPath $Path -AclObject $acl;Assert-RootEnumerationOrdinary $Path $true|Out-Null}
function Write-RootEnumerationNew([string]$Path,[byte[]]$Bytes,[long]$Maximum){if($Bytes.Length -gt $Maximum){throw 'Diagnostic artifact exceeds bound.'};$f=New-Object IO.FileStream($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$f.Write($Bytes,0,$Bytes.Length);$f.Flush($true)}finally{$f.Dispose()}}
function Export-RootEnumeration($Native,[string]$Role,[string]$Root){if($Role -cnotin @('A','B','empty','nonempty') -or $Native.queries.Count -gt 9){throw 'Diagnostic query export bound differs.'};$rows=@();$index=0;foreach($q in $Native.queries){$bytes=[byte[]]$q.bytes;if($bytes.Length -ne $q.capacity -or $bytes.Length -gt 4096){throw 'Diagnostic buffer capture differs.'};$name=$Role+'-'+$index.ToString('D2')+'.bin';Write-RootEnumerationNew ($Root+'\'+$name) $bytes 4096;$row=[ordered]@{};foreach($p in $q.PSObject.Properties){if($p.Name -cne 'bytes'){$row[$p.Name]=$p.Value}};$row.artifact=$name;$row.sha256=(Get-FileHash -LiteralPath ($Root+'\'+$name) -Algorithm SHA256).Hash.ToLowerInvariant();$rows+=,[pscustomobject]$row;$index++};$plain=[ordered]@{};foreach($p in $Native.PSObject.Properties){$plain[$p.Name]=$p.Value};$plain.queries=$rows;[pscustomobject]$plain}
if(-not $PSCmdlet.ShouldProcess('exact failed F:/S: preparation and new C: controls','Read bounded native directory queries; create only private C: control files')){[pscustomobject]@{Status='what-if';ConversionQualified=$false};return}
Assert-RootEnumerationPins $RunId $SourceEvidenceSha256 $ShadowEvidenceSha256
if($ObservationId.Length -ne 32 -or $env:COMPUTERNAME -cne 'N2R-WIN11' -or $env:SystemDrive -cne 'C:' -or -not [Environment]::Is64BitProcess){throw 'Exact x64 lab guest required.'}
$held=New-Object 'Collections.Generic.List[IO.FileStream]';$record=$null;$unknown=$false
try{
 $source=Read-RootEnumerationPin ('C:\ntfs2refs\retained-source\'+$RunId+'\prepare.json') $SourceEvidenceSha256 1MB;$shadow=Read-RootEnumerationPin ('C:\ntfs2refs\shadow-platform\'+$RunId+'\prepare.json') $ShadowEvidenceSha256 1MB;Assert-RootEnumerationProofs $source $shadow $RunId
 $before=@(Get-Disk);Assert-RootEnumerationInventory $before;foreach($role in @('A','B')){$letter=if($role -ceq 'A'){'F'}else{'S'};$proof=if($role -ceq 'A'){$source}else{$shadow};$part=Get-Partition -DriveLetter $letter;Assert-RootEnumerationLive (Get-Disk -Number $part.DiskNumber) $part (Get-Volume -DriveLetter $letter) $proof $role}
 $cp=Get-Partition -DriveLetter C;$cv=Get-Volume -DriveLetter C;if($cp.DiskNumber -ne 0 -or -not $cp.IsBoot -or $cv.FileSystem -cne 'NTFS'){throw 'C: controls must be on enrolled OS partition.'}
 $sources=@(@('NativeRetainedFixture.cs','b1152679f8b581cace5114d7aa7ec6954bcf968300d1610015aa04607c7eb9df'),@('NativeRetainedFixture.Windows.cs','0304b0dd80ba633a11483dda2a56b46824a7ded75314801bb327b64c587f8932'),@('NativeRootEnumeration.cs',$DiagnosticSourceSha256));foreach($x in $sources){Read-RootEnumerationPin (Join-Path $PSScriptRoot $x[0]) $x[1] 128KB -Text|Out-Null}
 if(('Ntfs2Refs.NativeRetainedFixture' -as [type]) -or ('Ntfs2Refs.NativeRootEnumeration' -as [type])){throw 'Fresh process required for frozen diagnostic parser.'};Add-Type -Path @($sources|ForEach-Object{Join-Path $PSScriptRoot $_[0]})
 Assert-RootEnumerationOrdinary 'C:\ntfs2refs' $true|Out-Null;$parent='C:\ntfs2refs\root-enumeration';if(-not(Test-Path -LiteralPath $parent)){New-RootEnumerationDirectory $parent};Assert-RootEnumerationOrdinary $parent $true|Out-Null;$runRoot=$parent+'\'+$RunId;if(-not(Test-Path -LiteralPath $runRoot)){New-RootEnumerationDirectory $runRoot};Assert-RootEnumerationOrdinary $runRoot $true|Out-Null;$output=$runRoot+'\'+$ObservationId;New-RootEnumerationDirectory $output
 $record=[ordered]@{schemaVersion=1;kind='native-root-enumeration-diagnostic';runId=$RunId;observationId=$ObservationId;status='started';sourceEvidenceSha256=$SourceEvidenceSha256;shadowEvidenceSha256=$ShadowEvidenceSha256;sourceHashes=@($sources|ForEach-Object{[pscustomobject]@{name=$_[0];sha256=$_[1]}});scriptSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();createdUtc=[DateTime]::UtcNow.ToString('o');source=$source;shadow=$shadow.shadow;beforeDisks=@($before|Select-Object Number,UniqueId,Guid,Size,IsOffline,IsReadOnly);afterDisks=$null;controlsCreated=$false;controlPayloadBytesWritten=0;controlRoot=$output+'\controls';observations=@();operationCompletionKnown=$true;cleanupComplete=$false;sourceShadowWriteRequestsIssued=$false;fileTimeSetterRequestsIssued=$false;accessTimeBookkeepingMayOccur=$true;initialEmptyStateProven=$false;existingFixtureErrorGuardChanged=$false;conversionQualified=$false}
 $json=(New-Object Text.UTF8Encoding($false)).GetBytes(($record|ConvertTo-Json -Depth 18));Write-RootEnumerationNew ($output+'\intent.json') $json 1MB
 New-RootEnumerationDirectory $record.controlRoot;foreach($name in @('empty','nonempty')){New-RootEnumerationDirectory ($record.controlRoot+'\'+$name)};Write-RootEnumerationNew ($record.controlRoot+'\nonempty\marker.bin') ([byte[]]@(0x4e)) 1;$record.controlsCreated=$true;$record.controlPayloadBytesWritten=1
 foreach($spec in @(@('A','F:\',$source.volume.guid,1,16MB,52GB),@('B','S:\',$shadow.shadow.volumeGuid,3,16MB,52GB),@('empty',($record.controlRoot+'\empty'),$cv.UniqueId,0,$cp.Offset,$cp.Size),@('nonempty',($record.controlRoot+'\nonempty'),$cv.UniqueId,0,$cp.Offset,$cp.Size))){$unknown=$true;$native=[Ntfs2Refs.NativeRootEnumeration]::Capture($spec[1],$spec[2],$spec[3],$spec[4],$spec[5]);$unknown=-not $native.operationCompletionKnown;$record.observations+=,(Export-RootEnumeration $native $spec[0] $output);if($unknown -or -not $native.cleanupComplete){throw 'Native diagnostic completion/cleanup unresolved.'}}
 $after=@(Get-Disk);Assert-RootEnumerationInventory $after;foreach($role in @('A','B')){$letter=if($role -ceq 'A'){'F'}else{'S'};$proof=if($role -ceq 'A'){$source}else{$shadow};$part=Get-Partition -DriveLetter $letter;Assert-RootEnumerationLive (Get-Disk -Number $part.DiskNumber) $part (Get-Volume -DriveLetter $letter) $proof $role};$record.afterDisks=@($after|Select-Object Number,UniqueId,Guid,Size,IsOffline,IsReadOnly);$record.cleanupComplete=$true;$record.status='observed-no-guard-change'
}catch{if($record){$record.status='failed-preserved';$record.error=$_.Exception.ToString()}else{throw}}
finally{if($record){$record.operationCompletionKnown=-not $unknown;$record.finishedUtc=[DateTime]::UtcNow.ToString('o');$json=(New-Object Text.UTF8Encoding($false)).GetBytes(($record|ConvertTo-Json -Depth 25));Write-RootEnumerationNew ($output+'\root-enumeration.json') $json 1MB};if(-not $unknown){foreach($h in $held){$h.Dispose()}}}
[pscustomobject]@{Status=$record.status;RunId=$RunId;ObservationId=$ObservationId;EvidenceDirectory=$output;OperationCompletionKnown=$record.operationCompletionKnown;CleanupComplete=$record.cleanupComplete;ConversionQualified=$false}
